const nav=document.querySelector('.links'),menu=document.querySelector('.menu');menu?.addEventListener('click',()=>nav.classList.toggle('open'));const io=new IntersectionObserver(es=>es.forEach(e=>{if(e.isIntersecting)e.target.classList.add('in')}),{threshold:.12});document.querySelectorAll('.reveal').forEach(el=>io.observe(el));const a=document.querySelector('.ambient');if(a)window.addEventListener('pointermove',e=>{a.style.left=e.clientX+'px';a.style.top=e.clientY+'px'});document.querySelectorAll('a[href]').forEach(l=>{const u=new URL(l.href);if(u.origin===location.origin&&!l.hash)l.addEventListener('click',e=>{if(e.metaKey||e.ctrlKey)return;document.body.animate([{opacity:1},{opacity:0}],{duration:260,fill:'forwards'});})});document.body.animate([{opacity:0},{opacity:1}],{duration:700,fill:'forwards',easing:'cubic-bezier(.16,1,.3,1)'});
